# -*- coding: utf-8 -*-
import re

with open('app/src/main/java/com/example/data/WorshipData.kt', 'r', encoding='utf-8') as f:
    content = f.read()

match = re.search(r'val sahifaSajjadiya = listOf\((.*?)\)\s+val generalPrayers =', content, re.DOTALL)
if not match:
    print("Could not find sahifaSajjadiya block!")
    exit(1)

block = match.group(1)
elements = re.split(r'(?=Pair\(\"الدعاء)', block)
elements = [e.strip() for e in elements if e.strip()]

for idx in range(len(elements)):
    elements[idx] = elements[idx].rstrip()
    if elements[idx].endswith(','):
        elements[idx] = elements[idx][:-1].rstrip()

text_14 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
يَامَنْ لاَ يَخْفَى عَلَيْهِ أَنْبَآءُ الْمُتَظَلِّمِينَ وَيَا مَنْ لاَ يَحْتَاجُ فِي قِصَصِهِمْ إلَى شَهَادَاتِ الشَّاهِدِينَ وَيَا مَنْ قَرُبَتْ نُصْرَتُهُ مِنَ الْمَظْلُومِينَ وَيَا مَنْ بَعُدَ عَوْنُهُ عَنِ الظَّالِمِينَ
قَدْ عَلِمْتَ يَا إلهِي مَا نالَنِي مِنْ [فُلاَنِ بْنِ فُلاَن] مِمَّا حَظَرْتَ وَانْتَهَكَهُ مِنّي مِمَّا حَجَزْتَ عَلَيْهِ بَطَراً فِي نِعْمَتِكَ عِنْدَهُ وَاغْتِرَاراً بِنَكِيرِكَ عَلَيْهِ
فَصَلِّ اللَّهُمَّ عَلَى مُحَمَّد وَآلِهِ وَخُذْ ظَالِمِي وَعَدُوِّي عَنْ ظُلْمِي بِقُوَّتِكَ وَافْلُلْ حَدَّهُ عَنِّي بِقُدْرَتِكَ وَاجْعَلْ لَهُ شُغْلاً فِيَما يَلِيهِ وَعَجْزاً عَمَّا يُناوِيْهِ أللَّهُمَّ وَصَلِّ عَلَى مُحَمَّد وَآلِهِ وَلاَ تُسَوِّغْ لَهُ ظُلْمِي وَأَحْسِنْ عَلَيْـهِ عَوْنِي، وَاعْصِمْنِي مِنْ مِثْـلِ أَفْعَالِهِ، وَلا تَجْعَلْنِي فِي مِثْلِ حَالِهِ.
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ، وَأَعِدْنِي عَلَيْهِ عَدْوى حَاضِرَةً تَكُونُ مِنْ غَيْظِي بِهِ شِفَاءً، وَمِنْ حَنَقِي عَلَيْهِ وَفَاءً.
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ وَعَوِّضْنِي مِنْ ظُلْمِهِ لِي عَفْوَكَ، وَأَبْدِلْنِي بِسُوْءِ صنِيعِهِ بِيْ رَحْمَتَكَ، فَكُلُّ مَكْرُوه جَلَلٌ دُونَ سَخَطِكَ، وَكُلُّ مَرْزِئَة سَوَاءٌ مَعَ مَوْجِدَتِكَ.
أللَّهُمَّ فَكَمَا كَـرَّهْتَ إلَيَّ أَنْ أَظْلِمَ فَقِنِي مِنْ أَنْ أُظْلَمَ.
أللَّهُمَّ لاَ أَشْكُوإلَى أَحَد سِوَاكَ، وَلاَ أَسْتَعِينُ بِحَاكِم غَيْرِكَ حَاشَاكَ فَصَلِّ عَلَى مُحَمَّد وَآلِهِ، وَصِلْ دُعَائِي بِالاجَابَةِ، وَأَقْرِنْ شِكَايَتِي بِالتَّغْيِيرِ.
أَللَّهُمَّ لا تَفْتِنِّي بِالْقُنُوطِ مِنْ إنْصَافِكَ، وَلاَ تَفْتِنْـهُ بِالاَمْنِ مِنْ إنْكَارِكَ، فَيُصِرَّ عَلَى ظُلْمِي وَيُحَاضِرَنِي بِحَقِّيْ وَعَرِّفْهُ عَمَّا قَلِيْل مَا أَوْعَدْتَ الظَّالِمِينَ، وَعَرِّفْنِي مَا وَعَدْتَ مِنْ إجَابَةِ الْمُضْطَرِّينَ. أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ، وَوَفِّقْنِي لِقَبُولِ مَا قَضَيْتَ لِيْ وَعَليَّ، وَرَضِّنِيْ بِمَا أَخَذْتَ لي وَمِنِّي وَاهْـدِنِي لِلَّتِيْ هِي أَقْوَمُ وَاسْتَعْمِلْنِي بِمَا هُوَ أَسْلَمُ.
أللَّهُمَّ وَإنْ كَانَتِ الْخِيَرَةُ لِيْ عِنْدَكَ فِي تَأْخِيرِ الاَخْذِ لِي وَتَرْكِ الانْتِقَامِ مِمَّنْ ظَلَمَنِيْ إلَى يَوْمِ الْفَصْلِ وَمَجْمَعِ الْخَصْمِ، فَصَلِّ عَلَى مُحَمَّد وَآلِهِ، وَأَيِّدْنِي مِنْكَ بِنِيَّة صَادِقَة وَصَبْر دَائِم، وَأَعِذْنِي مِنْ سُوءِ الرَّغْبَةِ، وَهَلَعِ أَهْلِ الْحِرْصِ، وَصَوِّرْ فِي قَلْبِي مِثَالَ مَا ادَّخَـرْتَ لِي مِنْ ثَوَابِـكَ، وَأَعْدَدْتَ لِخَصْمِي مِنْ جَزَائِكَ وَعِقَابِكَ، وَاجْعَلْ ذَلِكَ سَبَباً لِقَنَاعَتِي بِمَا قَضَيْتَ، وَثِقَتِي بِمَا تَخَيَّرْتَ، آمِينَ رَبَّ الْعَالَمِينَ، إنَّكَ ذُوالْفَضْلِ الْعَظِيمِ، وَأَنْتَ عَلَى كُلِّ شَيْء قَدِيرٌ."""

text_15 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أللَّهُمَّ لَكَ الْحَمْدُ عَلَى مَا لَمْ أَزَلْ أَتَصَرَّفُ فِيهِ مِنْ سَلاَمَةِ بَدَنِي، وَلَكَ الْحَمْدُ عَلَى مَا أَحْدَثْتَ بِيْ مِنْ عِلَّةٍ فِي جَسَـدِي.
فَمَا أَدْرِي يَـا إلهِي، أَيُّ الْحَالَيْنِ أَحَقُّ بِالشُّكْرِ لَكَ، وَأَيُّ الْوَقْتَيْنِ أوْلَى بِالْحَمْدِ لَكَ، أَوَقْتُ الصِّحَةِ الَّتِي هَنَّـأْتَنِي فِيهَا طَيِّبَاتِ رِزْقِكَ، وَنَشَّطْتَنِي بِهَا لابْتِغاءِ مَرْضَاتِكَ وَفَضْلِكَ، وَقَوَّيْتَنِي مَعَهَا عَلَى مَـا وَفَّقْتَنِي لَهُ مِنْ طَـاعَتِـكَ أَمْ وَقْتُ الْعِلَّةِ الَّتِي مَحَّصْتَنِي بِهَا، وَالنِّعَمِ الَّتِي أَتْحَفْتَنِي بِهَا تَخْفِيفاً لِمَا ثَقُلَ بِهِ عَلَى ظَهري مِنَ الْخَطِيئاتِ وَتَطْهيراً لِمَا انْغَمَسْتُ فيهِ مِنَ السَّيِّئاتِ، وَتَنْبِيهاً لِتَنَاوُلِ التَّوْبَةِ، وَتَذْكِيراً لِمَحْوِ الْحَوْبَةِ بِقَدِيمِ النِّعْمَةِ، وَفِي خِلاَلِ ذَلِكَ مَا كَتَبَ لِيَ الْكَاتِبَانِ مِنْ زَكِيِّ الاعْمَالِ، مَا لا قَلْبٌ فَكَّرَ فِيهِ، وَلا لِسَانٌ نَطَقَ بِهِ وَلاَ جَارِحَةٌ تَكَلَّفَتْهُ بَلْ إفْضَالاً مِنْكَ عَلَيَّ، وَإحْسَاناً مِنْ صَنِيعِـكَ إلَيَّ.
أللَّهُمَّ فَصَلِّ عَلَى مُحَمَّـد وَآلِـهِ وَحَبِّبْ إلَيّ مَـا رَضِيتَ لِي، وَيَسِّرْ لِي مَا أَحْلَلْتَ بِيْ، وَطَهِّرْنِي مِنْ دَنَسِ مَا أَسْلَفْتُ، وَامْحُ عَنِّي شَرَّ مَا قَـدَّمْتُ، وَأَوْجِدْنِي حَلاَوَةَ الْعَافِيَةِ، وَأَذِقْنِي بَرْدَ السَّلاَمَةِ وَاجْعَلْ مَخْرَجِي عَنْ عِلَّتِي إلَى عَفْوِكَ، وَمُتَحَوَّلِي عَنْ صَرْعَتِي إلَى تَجَاوُزِكَ، وَخَلاصِي مِنْ كَرْبِي إلَى رَوْحِكَ، وَسَلاَمَتِي مِنْ هَذِهِ الشِّدَّةِ إلَى فَرَجِكَ، إنَّكَ الْمُتَفَضِّلُ بِالاِحْسَانِ، الْمُتَطَوِّلُ بِالامْتِنَانِ، الْوَهَّابُ الْكَرِيمُ، ذُوالْجَلاَلِ وَالاكْرَامِ."""

text_13 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أللَّهُمَّ يَا مُنْتَهَى مَطْلَبِ الْحَاجَاتِ، وَيَا مَنْ عِنْدَه نَيْلُ الطَّلِبَاتِ، وَيَا مَنْ لا يَبِيْعُ نِعَمَهُ بالاثْمَانِ، وَيَا مَنْ لا يُكَدِّرُ عَطَايَاهُ بِالامْتِنَانِ، وَيَا مَنْ يُسْتَغْنَى بِهِ وَلاَ يُسْتَغْنَى عَنْهُ، وَيَا مَنْ يُرْغَبُ إلَيْهِ وَلا يُرْغَبُ عَنْهُ.
وَيَا مَنْ لا تُفنى خَزَآئِنَهُ الْمَسَائِلُ، وَيَا مَنْ لاَ تُبَدِّلُ حِكْمَتَهُ الْوَسَائِلُ.
وَيَا مَنْ لاَ تَنْقَطِعُ عَنْهُ حَوَائِجُ الْمُحْتَاجِينَ وَيَا مَنْ لاَ يُعَنِّيهِ دُعَاءُ الدَّاعِينَ تَمَدَّحْتَ بِالْغَنَاءِ عَنْ خَلْقِكَ وَأَنْتَ أَهْلُ الْغِنَى عَنْهُمْ، وَنَسَبْتَهُمْ إلَى الفَقْرِ وَهُمْ أَهْلُ الْفَقْرِ إلَيْكَ.
فَمَنْ حَاوَلَ سَدَّ خَلَّتِهِ مِنْ عِنْدِكَ وَرَامَ صَرْفَ الْفَقْر عَنْ نَفْسِهِ بِكَ فَقَدْ طَلَبَ حَاجَتَهُ فِي مَظَانِّها وَأَتَى طَلِبَتَهُ مِنْ وَجْهِهَا وَمَنْ تَوَجَّهَ بِحَاجَتِهِ إلَى أَحَد مِنْ خَلْقِكَ أَوْ جَعَلَهُ سَبَبَ نُجْحِهَا دُونَكَ فَقَدْ تَعَرَّضَ لِلْحِرْمَانِ، وَاسْتَحَقَّ مِنْ عِنْدِكَ فَوْتَ الاِحْسَانِ.
أللَّهُمَّ وَلِي إلَيْكَ حَاجَةٌ قَـدْ قَصَّرَ عَنْهَـا جُهْدِي، وَتَقَطَّعَتْ دُونَهَا حِيَلِي، وَسَوَّلَتْ لِيْ نَفْسِي رَفْعَهَا إلَى مَنْ يَرْفَعُ حَوَائِجَهُ إلَيْكَ، وَلاَ يَسْتَغْنِي فِي طَلِبَاتِهِ عَنْكَ، وَهِيَ زَلَّةٌ مِنْ زَلَلِ الْخَاطِئِينَ، وَعَثْرَةٌ مِنْ عَثَراتِ الْمُذْنِبِينَ، ثُمَّ انْتَبَهْتُ بِتَذْكِيرِكَ لِي مِنْ غَفْلَتِي وَنَهَضْتُ بِتَوْفِيقِكَ مِنْ زَلَّتِي، وَنَكَصْتُ بِتَسْـدِيدِكَ عَنْ عَثْـرَتِي وَقُلْتُ: سُبْحَانَ رَبّي كَيْفَ يَسْأَلُ مُحْتَاجٌ مُحْتَاجـاً، وَأَنَّى يَرْغَبُ مُعْدِمٌ إلَى مُعْدِم؟!
فَقَصَدْتُكَ يا إلهِي بِالرَّغْبَةِ، وَأَوْفَدْتُ عَلَيْكَ رَجَائِي بِالثِّقَةِ بِكَ، وَعَلِمْتُ أَنَّ كَثِيرَ مَا أَسْأَلُكَ يَسِيرٌ فِي وُجْدِكَ، وَأَنَّ خَطِيرَ مَا أَسْتَوْهِبُكَ حَقِيرٌ فِيْ وُسْعِكَ، وَأَنَّ كَرَمَكَ لاَ يَضِيقُ عَنْ سُؤَال أحَد، وَأَنَّ يَدَكَ بِالْعَطايا أَعْلَى مِنْ كُلِّ يَد.
أللَهُمَّ فَصَلِّ عَلَى مُحَمَّد وَآلِهِ وَاحْمِلْنِي بِكَرَمِكَ عَلَى التَّفَضُّلِ، وَلاَ تَحْمِلْنِي بِعَدْلِكَ عَلَى الاسْتِحْقَاقِ، فَما أَنَا بِأَوَّلِ رَاغِبِ رَغِبَ إلَيْكَ فَأَعْطَيْتَهُ وَهُوَ يَسْتَحِقُّ الْمَنْعَ، وَلاَ بِأَوَّلِ سَائِل سَأَلَكَ فَأَفْضَلْتَ عَلَيْهِ وَهُوَ يَسْتَوْجِبُ الْحِرْمَانَ.
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ، وَكُنْ لِدُعَائِي مُجِيباً، وَمِنْ نِدائِي قَرِيباً، وَلِتَضَرُّعِي رَاحِماً، وَلِصَوْتِي سَامِعاً وَلاَ تَقْطَعْ رَجَائِي عَنْكَ وَلا تَبُتَّ سَبَبِي مِنْكَ وَلاَ تُوَجِّهْنِي فِي حَاجَتيْ هَذِهِ وَغَيْرِهَا إلى سِوَاكَ وَتَوَلَّنِي بِنُجْحِ طَلِبَتِي، وَقَضاءِ حَاجَتِي، وَنَيْلِ سُؤْلِي قَبْلَ زَوَالِي عَنْ مَوْقِفِي هَذَا بِتَيسِيرِكَ لِيَ الْعَسِيْرَ، وَحُسْنِ تَقْدِيرِكَ لِي فِي جَمِيعِ الاُمُورِ.
وَصَلِّ عَلَى مُحَمَّد وَآلِهِ صَلاَةً دَائِمَةً نَامِيَةً لاَ انْقِطَاعَ لاِبَدِهَا، وَلا مُنْتَهَى لاِمَدِهَا، وَاجْعَلْ ذَلِكَ عَوْناً لِيْ وَسَبَباً لِنَجَاحِ طَلِبَتِي إنَّكَ وَاسِعٌ كَرِيْمٌ.
وَمِنْ حَاجَتِي يَا رَبِّ كَذَا وَكَذَا ـ وَتَذْكُرُ حَاجَتَكَ ثمّ تَسْجُـدُ وَتَقُولُ فِي سُجُودِكَ: ـ فَضْلُكَ آنَسَنِي، وَإحْسَانُكَ دَلَّنِي، فَأَسْأَلُكَ بِكَ وَبِمُحَمَّـد وَآلِهِ صَلَواتُكَ عَلَيْهمْ أَنْ لاَ تَرُدَّنِي خَائِباً"""

